/bin/sh -lc "python3 << 'EOF'
import openpyxl

book = openpyxl.load_workbook('/work/camp_register.xlsx')
ws = book['Camp Register']

# Check all rows to find all camp headers
for row_idx, row in enumerate(ws.iter_rows(values_only=True)):
    if row and row[0] and not any(str(cell) == 'S.No' for cell in row[1:5] if cell):
        if 'Health Camp' in str(row[0]):
            print(f\"Row {row_idx+1}: {row[0]}\")
EOF"

